fn page_is_pfmemalloc(page: *const page) -> bool {
// lru.next has bit 1 set if the page is allocated from the
// pfmemalloc reserves.  Callers may simply overwrite it if
// they do not need to preserve that information.
((unsafe { (*page).__slate_anon_1.__slate_anon_0.__slate_anon_0.lru.next }) as u64) & BIT!(1i32) != 0
}

fn want_init_on_alloc(flags: u32) -> bool {
if static_branch_maybe__2!(unsafe { core::ptr::addr_of_mut!(init_on_alloc) }) != 0 {
return true;
}
flags & (BIT!(8i32) as u32) != 0
}

