#[derive(Clone, Copy)]
struct reciprocal_value {
    m: u32,
    sh1: u8,
    sh2: u8,
}


fn reciprocal_divide(a: u32, R: reciprocal_value) -> u32 {
let t: u32 = ((a as u64).wrapping_mul(R.m as u64) >> 32i32) as u32;
t.wrapping_add(a.wrapping_sub(t) >> (R.sh1 as i32)) >> (R.sh2 as i32)
}

