// no flags
// a kmalloc_nolock() allocation
// a flag for alloc_slab_obj_exts()
// prevent kmalloc() recursion
// prevent obj_exts array allocation
// no flags
// spinning not allowed
fn to_alloc_flags(free_flags: u32) -> u32 {
if free_flags & 1 != 0 {
return 1;
} else {
return 0;
}
}

fn alloc_flags_allow_spinning(alloc_flags: u32) -> bool {
alloc_flags & 1 == 0
}

fn free_flags_allow_spinning(free_flags: u32) -> bool {
free_flags & 1 == 0
}

