fn page_slab(mut page: *const page) -> *mut slab {
page = compound_head!(page);
if data_race!((unsafe { (*page).__slate_anon_2.page_type }) >> 24i32) != 245 {
page = core::ptr::null::<page>();
}
page as *mut slab
}

