fn __obj_to_index(cache: *const kmem_cache, addr: *mut (), obj: *const ()) -> u32 {
reciprocal_divide(((unsafe { (kasan_reset_tag(obj) as *const u8).offset_from(addr as *const u8) }) as i64) as u32, unsafe { (*cache).reciprocal_size })
}

fn obj_to_index(cache: *const kmem_cache, slab: *const slab, obj: *const ()) -> u32 {
if is_kfence_address(obj) {
return 0;
}
__obj_to_index(cache, slab_address(slab), obj)
}

fn kvmalloc_obj_start_addr(head: *mut ()) -> *mut () {
let mut offset: u64 = 0;
if unlikely!(unsafe { is_vmalloc_addr(head as *const ()) }) != 0 {
offset = offset_in_page!(head);
} else {
let slab: *mut slab = virt_to_slab(head as *const ());
if slab.is_null() {
offset = offset_in_page!(head);
} else {
if is_kfence_address(head as *const ()) {
offset = ((unsafe { (head as *const u8).offset_from(kfence_object_start(head as *const ()) as *const u8) }) as i64) as u64;
} else {
let s: *mut kmem_cache = unsafe { (*slab).slab_cache };
let idx: u32 = __obj_to_index(s as *const kmem_cache, slab_address(slab as *const slab), head as *const ());
let mut obj: *mut () = (unsafe { (slab_address(slab as *const slab) as *const u8).wrapping_offset(unsafe { (*s).size }.wrapping_mul(idx) as isize) }) as *mut ();
obj = fixup_red_left(s, obj);
obj = kasan_reset_tag(obj as *const ());
offset = ((unsafe { (kasan_reset_tag(head as *const ()) as *const u8).offset_from(obj as *const u8) }) as i64) as u64;
}
}
}
(unsafe { (head as *const u8).wrapping_offset(-(offset as isize)) }) as *mut ()
}

fn size_index_elem(bytes: u32) -> u32 {
bytes.wrapping_sub(1) / 8
}

fn kmalloc_slab(size: u64, mut b: *mut [*mut kmem_cache; 14], flags: u32, token: __SlateRecord_slab_h_532, alloc_flags: u32) -> *mut kmem_cache {
let mut index: u32 = 0;
let mut r#type: u32 = kmalloc_type(flags, token);
if alloc_flags & 8 != 0 {
r#type = 0;
}
if b.is_null() {
b = unsafe { core::ptr::addr_of_mut!(kmalloc_caches) as *mut [*mut kmem_cache; 14] }.wrapping_offset((r#type as u32) as isize);
}
if size <= 192 {
index = (unsafe { kmalloc_size_index[size_index_elem(size as u32) as usize] }) as u32;
} else {
index = fls(size.wrapping_sub(1) as u32) as u32;
}
unsafe { *((*b).as_mut_ptr() as *mut *mut kmem_cache).wrapping_offset(index as isize) }
}

fn is_kmalloc_cache(s: *mut kmem_cache) -> bool {
(unsafe { (*s).flags }) & __SLAB_FLAG_BIT!(3i32) != 0
}

